import {normalizeBusiness,estimateProject,safeSnapshot,compareProjects,encodeReviewLink} from './business.mjs?v=cad18';
import {projectPDF} from './document-export.js?v=cad18';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const download=(blob,name)=>{const a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);};
const categories={body:'Корпус',front:'Фасад',top:'Столешница',hardware:'Фурнитура',labor:'Работа'},units={m2:'м²',m:'пог. м',piece:'шт.',module:'модуль'};
export function installBusiness({getProject,replaceProject,scene,toast,commit}){const button=document.createElement('button');button.id='business-open';button.textContent='Проект и смета';document.querySelector('#export-open').before(button);const dialog=document.createElement('dialog');dialog.id='business-dialog';dialog.className='pro-dialog';document.body.append(dialog);let tab='estimate',moduleId=null,removedVersion=null;const key='batesto-pro-versions-v1';const versions=()=>{try{const v=JSON.parse(localStorage.getItem(key)||'[]');return Array.isArray(v)?v.slice(0,12):[];}catch{return [];}};const b=()=>{const p=getProject();return p.business=normalizeBusiness(p.business);};
function render(){if(!dialog.open)return;const p=getProject(),data=b(),estimate=estimateProject(p),readonly=document.body.dataset.reviewReadonly==='true';moduleId=p.modules.some(m=>m.id===moduleId)?moduleId:p.modules[0]?.id;const m=p.modules.find(m=>m.id===moduleId);const options=(list,selected)=>'<option value="">Не назначено</option>'+list.map(c=>`<option value="${esc(c.id)}" ${c.id===selected?'selected':''}>${esc(c.name)} · ${esc(c.sku||'без артикула')}</option>`).join('');const assign=data.assignments[moduleId]||{};dialog.innerHTML=`<button data-close class="pro-close">Закрыть</button><h2>Проект и смета</h2><div class="pro-actions">${[['estimate','Смета'],['catalog','Каталог'],['versions','Версии'],['share','Обсуждение']].map(([id,title])=>`<button data-tab="${id}" aria-pressed="${tab===id}">${title}</button>`).join('')}<button id="pdf-download">Скачать PDF</button></div><div id="business-content"></div><p id="business-error" class="pro-error"></p>`;const content=dialog.querySelector('#business-content');if(tab==='estimate'){content.innerHTML=`<p>Цены вводятся мастерской. Расход — геометрическая оценка площади без карт раскроя, отходов и доставки. Неназначенная фурнитура отмечается отдельно.</p><h3>${estimate.complete?'Предварительная сумма':'Учтённая сумма — расчёт неполный'}: ${estimate.subtotal.toLocaleString('ru-RU')} ₽</h3><p>${estimate.missing.length} незаполненных позиций</p>${m?`<label>Настроить модуль<select id="estimate-module">${p.modules.map(m=>`<option value="${esc(m.id)}" ${m.id===moduleId?'selected':''}>${esc(m.name)} · ${m.width} мм</option>`).join('')}</select></label><div class="pro-grid">${['body','front','top','labor'].map(type=>`<label>${categories[type]}<select data-assign="${type}" ${readonly?'disabled':''}>${options(data.catalog.filter(c=>c.category===type),assign[type])}</select></label>`).join('')}</div><h3>Фурнитура модуля</h3>${(assign.hardware||[]).map((h,i)=>`<div class="pro-row"><label>Позиция<select data-hardware="${i}" ${readonly?'disabled':''}>${options(data.catalog.filter(c=>c.category==='hardware'),h.catalogId)}</select></label><label>Количество<input type="number" min="0" max="1000" step="1" data-quantity="${i}" value="${h.quantity}" ${readonly?'disabled':''}></label><button data-remove-hardware="${i}" ${readonly?'disabled':''}>Убрать</button></div>`).join('')}<button id="hardware-add" ${readonly?'disabled':''}>+ Фурнитура</button>`:''}<h3>Позиции расчёта</h3><table><thead><tr><th>Модуль / позиция</th><th>Кол-во</th><th>Цена</th><th>Сумма ₽</th></tr></thead><tbody>${estimate.items.map(i=>`<tr><td>${esc(i.module)}<br>${esc(i.name)} · ${esc(i.sku)}</td><td>${i.quantity.toFixed(2)} ${units[i.unit]}</td><td>${i.rate??'—'}</td><td>${i.total??'нет цены'}</td></tr>`).join('')}</tbody></table><details><summary>Что ещё заполнить (${estimate.missing.length})</summary><ul>${estimate.missing.map(t=>`<li>${esc(t)}</li>`).join('')}</ul></details>`;}else if(tab==='catalog'){content.innerHTML=`<p>Ваши артикулы и согласованные расценки. Пустая цена означает «неизвестно». 0 ₽ используется только при явно введённом нуле.</p><div class="pro-actions"><button id="catalog-add" ${readonly?'disabled':''}>+ Позиция</button><button id="catalog-export">Экспорт JSON</button><button id="catalog-template">Шаблон JSON</button><label>Импорт JSON<input id="catalog-import" type="file" accept="application/json,.json" ${readonly?'disabled':''}></label></div>${data.catalog.map((c,i)=>`<div class="pro-card" data-catalog="${i}"><div class="pro-grid"><label>Название<input data-cat="name" value="${esc(c.name)}" ${readonly?'disabled':''}></label><label>Артикул<input data-cat="sku" value="${esc(c.sku)}" ${readonly?'disabled':''}></label><label>Категория<select data-cat="category" ${readonly?'disabled':''}>${Object.entries(categories).map(([v,l])=>`<option value="${v}" ${v===c.category?'selected':''}>${l}</option>`).join('')}</select></label><label>Единица<select data-cat="unit" ${readonly?'disabled':''}>${Object.entries(units).map(([v,l])=>`<option value="${v}" ${v===c.unit?'selected':''}>${l}</option>`).join('')}</select></label><label>Цена ₽<input data-cat="rate" type="number" min="0" max="10000000" step="0.01" value="${c.rate??''}" ${readonly?'disabled':''}></label></div><button data-delete-cat="${i}" ${readonly?'disabled':''}>Удалить позицию</button></div>`).join('')}`;}else if(tab==='versions'){content.innerHTML=`<p>Версии — отдельные снимки на этом устройстве. Восстановление можно отменить. До 12 версий.</p>${removedVersion?'<button id="version-undo-delete">Вернуть удалённую версию</button>':''}<div class="pro-actions"><input id="version-label" placeholder="Название версии" maxlength="80"><button id="version-save" ${readonly?'disabled':''}>Сохранить версию</button></div>${versions().map((v,i)=>`<div class="pro-card"><strong>${esc(v.label)}</strong><p>${esc(v.date)} · ${v.project?.modules?.length||0} модулей</p><button data-compare="${i}">Сравнить с текущим</button><button data-restore="${i}" ${readonly?'disabled':''}>Восстановить</button><button data-delete-version="${i}" ${readonly?'disabled':''}>Удалить версию</button></div>`).join('')}<pre id="version-diff" style="white-space:pre-wrap"></pre>`;}else{content.innerHTML=`<p>Ссылка содержит снимок проекта для просмотра. Текущие права доступа сайта сохраняются. План-картинка не включается; данные проекта, каталога и сметы включаются. На localhost ссылка работает только на этом компьютере — для клиента создавайте её на опубликованном сайте.</p><button id="review-link">Создать ссылку просмотра</button><label>Ссылка<textarea id="review-url" readonly></textarea></label><button id="review-copy">Скопировать ссылку</button>`;}}
button.onclick=()=>{dialog.showModal();render();};dialog.onclick=async e=>{const btn=e.target.closest('button');if(!btn)return;try{if(btn.hasAttribute('data-close'))dialog.close();if(btn.dataset.tab){tab=btn.dataset.tab;render();}const data=b();if(btn.id==='catalog-add'){data.catalog.push({id:crypto.randomUUID(),name:'Новая позиция',sku:'',category:'body',unit:'m2',rate:null});commit();render();}if(btn.hasAttribute('data-delete-cat')){data.catalog.splice(+btn.dataset.deleteCat,1);commit();render();}if(btn.id==='catalog-export'||btn.id==='catalog-template'){const payload=btn.id==='catalog-export'?{catalog:data.catalog}:{catalog:[],schema:{id:'уникальный текст',sku:'артикул',name:'название',category:'body | front | top | hardware | labor',unit:'m2 | m | piece | module',rate:'число рублей или null'}};download(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),'Batesto — каталог.json');}if(btn.id==='hardware-add'){const c=data.catalog.find(c=>c.category==='hardware');if(!c)throw Error('Сначала добавьте фурнитуру в каталог');data.assignments[moduleId]||={hardware:[]};data.assignments[moduleId].hardware||=[];data.assignments[moduleId].hardware.push({catalogId:c.id,quantity:1});commit();render();}if(btn.hasAttribute('data-remove-hardware')){data.assignments[moduleId].hardware.splice(+btn.dataset.removeHardware,1);commit();render();}if(btn.id==='version-save'){const list=versions();if(list.length>=12)throw Error('Лимит 12 версий. Для дополнительных копий используйте экспорт JSON.');list.unshift({id:crypto.randomUUID(),label:dialog.querySelector('#version-label').value.trim()||'Версия '+(list.length+1),date:new Date().toLocaleString('ru-RU'),project:safeSnapshot(getProject())});localStorage.setItem(key,JSON.stringify(list));render();}if(btn.hasAttribute('data-delete-version')){const list=versions();removedVersion=list.splice(+btn.dataset.deleteVersion,1)[0];localStorage.setItem(key,JSON.stringify(list));render();}if(btn.id==='version-undo-delete'&&removedVersion){const list=versions();if(list.length>=12)throw Error('Сначала освободите место');list.unshift(removedVersion);localStorage.setItem(key,JSON.stringify(list));removedVersion=null;render();}if(btn.hasAttribute('data-compare')){dialog.querySelector('#version-diff').textContent=compareProjects(versions()[+btn.dataset.compare].project,getProject()).join('\n')||'Проекты совпадают';}if(btn.hasAttribute('data-restore')){replaceProject(versions()[+btn.dataset.restore].project,{source:'version',readOnly:false});dialog.close();toast('Версия восстановлена');}if(btn.id==='review-link')dialog.querySelector('#review-url').value=await encodeReviewLink(getProject(),location.href);if(btn.id==='review-copy'){const text=dialog.querySelector('#review-url').value;if(!text)throw Error('Сначала создайте ссылку');await navigator.clipboard.writeText(text);toast('Ссылка скопирована');}if(btn.id==='pdf-download'){btn.disabled=true;btn.textContent='Создаём PDF…';const pdf=await projectPDF(getProject(),scene);download(pdf,'Batesto — проект.pdf');btn.disabled=false;btn.textContent='Скачать PDF';}}catch(err){dialog.querySelector('#business-error').textContent=err.message;}finally{const pdf=dialog.querySelector('#pdf-download');if(pdf){pdf.disabled=false;pdf.textContent='Скачать PDF';}}};
let editTimer;dialog.addEventListener('input',e=>{const el=e.target;if(!el.dataset.cat)return;const data=b(),index=+el.closest('[data-catalog]').dataset.catalog,c=data.catalog[index];c[el.dataset.cat]=el.dataset.cat==='rate'?(el.value===''?null:Number(el.value)):el.value;getProject().business=normalizeBusiness(data);clearTimeout(editTimer);editTimer=setTimeout(()=>commit({inspector:false}),250);});
dialog.onchange=async e=>{clearTimeout(editTimer);try{const el=e.target,data=b();if(el.id==='estimate-module'){moduleId=el.value;render();return;}if(el.dataset.cat){const c=data.catalog[+el.closest('[data-catalog]').dataset.catalog];c[el.dataset.cat]=el.dataset.cat==='rate'?(el.value===''?null:Number(el.value)):el.value;getProject().business=normalizeBusiness(data);commit();render();}if(el.dataset.assign){data.assignments[moduleId]||={hardware:[]};data.assignments[moduleId][el.dataset.assign]=el.value;commit();render();}if(el.hasAttribute('data-hardware')||el.hasAttribute('data-quantity')){const i=+(el.dataset.hardware??el.dataset.quantity);data.assignments[moduleId].hardware[i][el.hasAttribute('data-hardware')?'catalogId':'quantity']=el.hasAttribute('data-hardware')?el.value:Number(el.value);commit();render();}if(el.id==='catalog-import'){const file=el.files[0];if(!file)return;if(file.size>200000)throw Error('Каталог до 200 КБ');const parsed=JSON.parse(await file.text());if(!Array.isArray(parsed.catalog))throw Error('Нужен объект с массивом catalog');getProject().business=normalizeBusiness({...data,catalog:parsed.catalog});commit();render();}}catch(err){dialog.querySelector('#business-error').textContent=err.message;}finally{const pdf=dialog.querySelector('#pdf-download');if(pdf){pdf.disabled=false;pdf.textContent='Скачать PDF';}}};return {render};}
